var cur = parseInt(vars.hp, 10);
var dmg = Number(vars.damage) || 0;
if (isNaN(cur)) return { hasHp: 0, report: vars.target.name + " has no HP to lower." };
var now = Math.max(0, cur - dmg);
return { hasHp: 1, newHp: String(now), report: vars.target.name + ": -" + dmg + " HP (" + cur + " -> " + now + ")" };
